  assert.equal(totals.vat, 1746);
  assert.equal(totals.total, 10058);
});

test('invoiceTotals clamps negative amounts to 0', () => {
  // This shouldn't happen in normal usage, but we test the clamping
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'STICKER', qty: 1, unitPrice: 50, name: 'Sticker sheet', vatRate: 21, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // 1 × €0.50 = €0.50
  // 100% discount = €0.50
  // Total = €0.50 - €0.50 = €0.00 (clamped)
  assert.equal(totals.subtotal, 50);
  assert.equal(totals.discount, 50);
  assert.equal(totals.total, 0);
});

