test('invoiceTotals with tier discount applied', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // 10 × €95.00 = €950.00
  // 5% tier discount = €47.50
  // Amount after discount = €902.50
  // 21% VAT on €902.50 = €189.525 -> €189.52 (banker's rounding)
  // Total = €950.00 - €47.50 + €189.52 = €1,092.02
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

